from sage.all import *
from collections import Counter,defaultdict
K=QuadraticField(-1,'ii'); ii=K.gen()
R=PolynomialRing(K,names=['e0','e1','e2','q0','q1','r0','r1','kap','hb','t','s'])
e0,e1,e2,q0,q1,r0,r1,kap,hb,t,s=R.gens()
E=ExteriorAlgebra(R,names=['c0','c1','c2']); c0,c1,c2=E.gens()
def mono(ix):
    o=E.one()
    for j in ix:o*=E.gen(j)
    return o
def der(P,x):
    return sum((a.derivative(x)*mono(list(ix)) for ix,a in E(P).monomial_coefficients().items()),E.zero())
def Q(P):
    return c0*der(P,e0)+c1*der(P,e1)+c2*der(P,e2)+c1*der(P,q0)+2*c2*der(P,q1)
def integrate01(p,x): return p.integral(x).subs({x:1})-p.integral(x).subs({x:0})
f=s*(1-s); ef=(e0+e1*t+e2*t*t)*f; rf=(r0+r1*t)*s; qf=(q0+q1*t)*f
lag=kap/2*(ef.derivative(s)*rf.derivative(t)+rf.derivative(s)*ef.derivative(t))-kap*qf*rf.derivative(s)
S=integrate01(integrate01(lag,s),t)
B=kap/12*((r0+r1)*(c0+c1+c2)-r0*c0)
def Ward(P):return -ii*hb*Q(P)+B*E(P)
tests=[E(v)*g for v in [R.one(),e0,e1,q0,q1,r0,e0*q1,e2*r1,e0**2*q1] for g in [E.one(),c0,c1*c2]]
q_nil=all(Q(Q(v))==0 for v in tests)
ward_nil=all(Ward(Ward(v))==0 for v in tests)
phase_closed=(Q(E(S))+B==0)
missing_caps_nonzero=(Q(E(S))!=0)
endpoint_ghost_retained=(B!=0 and Q(B)==0)
gram_good=matrix(QQ,[[integrate01(u*v,s) for v in [R.one(),s]] for u in [f,s*f]])
gram_bad=matrix(QQ,[[integrate01(u*v,s) for v in [R.one(),s]] for u in [s-QQ(1)/2,s*s-QQ(1)/3]])
source_probe_rank=(gram_good.det()==QQ(1)/720 and gram_good.rank()==2 and gram_bad.rank()==1 and gram_bad*vector(QQ,[1,0])==0)
# Current insertion products derived from the actual complex Gaussian moments.
P=PolynomialRing(QQ,names=['x1','x2','y1','y2','z1','z2','b1','b2','h','k'])
x1,x2,y1,y2,z1,z2,b1,b2,h,k=P.gens()
xx=[x1,x2]; yy=[y1,y2]; zz=[z1,z2]; bb=[b1,b2]; cov=[h*k,2*h*k]
def gm(a,b,x,y,d):
    return sum((binomial(a,l)*binomial(b,l)*factorial(l)*d**l*y**(a-l)*x**(b-l) for l in range(min(a,b)+1)),P.zero())
def expectation(poly):
    ans=P.zero()
    for ex,coef in poly.dict().items():
        base=P(coef)
        for j in [0,1,2,3,8,9]:base*=P.gen(j)**ex[j]
        for n in range(2):base*=gm(ex[4+n],ex[6+n],xx[n],yy[n],cov[n])
        ans+=base
    return ans
def cap_product(F,G):
    return expectation(F.subs({y1:z1,y2:z2})*G.subs({x1:b1,x2:b2}))
def wick(F,G):
    ans=P.zero()
    for a in range(5):
        for b in range(5):
            df=F.derivative(y1,a).derivative(y2,b)
            dg=G.derivative(x1,a).derivative(x2,b)
            ans+=cov[0]**a*cov[1]**b/factorial(a)/factorial(b)*df*dg
    return ans
pairs=[(y1,x1),(y1*y1,x1*x1),(x2*y1*y1+y2,x1*x1*y2+x2),(x1*y2+x2*y1,x1*x2+y1*y2)]
cap_wick=all(cap_product(a,b)==wick(a,b) for a,b in pairs)
