cross_mode_normalization=(cap_product(y2,x2)-cap_product(x2,y2)==2*h*k)
# Unnormalized current-Fock monomials, no occupation cutoff.
def stress_vac(m):
    coeff=defaultdict(QQ)
    for r in range(1,m):coeff[tuple(sorted([r,m-r]))]+=QQ(1)/2
    return sum(a*a*prod(n**power*factorial(power) for n,power in Counter(key).items()) for key,a in coeff.items())
stress_norms=all(stress_vac(m)==QQ(m**3-m)/12 for m in range(2,18))
sharp_norms=all(sum(stress_vac(2*j+1)/QQ((2*j+1)**2) for j in range(1,L+1))==sum(QQ(2*j+1)-QQ(1)/(2*j+1) for j in range(1,L+1))/12 for L in range(1,7))
