sharp_positive=(stress_vac(3)>0 and stress_vac(5)>0)

# Normalized common-cut BRST quartet, keeping it in the field complex.
Rg=PolynomialRing(K,names=['xg','Bg']); Fg=Rg.fraction_field(); xg,Bg=[Fg(x) for x in Rg.gens()]
