def gmon(ids):
    p=Eg.one()
    for j in ids:p*=Eg.gen(j)
    return p
def gd(p,x):
    return sum((a.derivative(x)*gmon(list(ids)) for ids,a in Eg(p).monomial_coefficients().items()),Eg.zero())
def go(p,j):
    ans=Eg.zero()
    for ids,a in Eg(p).monomial_coefficients().items():
        ls=list(ids)
        if j in ls:
            pos=ls.index(j);ans+=(-1)**pos*a*gmon(ls[:pos]+ls[pos+1:])
    return ans
def Qg(p):return cg*gd(p,xg)+Bg*go(p,1)
Psi_g=bg*xg
Sgf=Bg*xg-bg*cg
quartet_exact=(Qg(Psi_g)==Sgf and Qg(Sgf)==0)
# hbar=1 here; factor i implements the declared paired odd normalization.
odd_norm=(ii*go(go(Eg.one()-ii*bg*cg,1),0)==1)
quartet_not_classical_quotient=(Qg(xg)==cg and Qg(bg)==Bg)
